"use strict";(globalThis.webpackChunkgrc||=[]).push([[66620],{42551(e){e.exports=JSON.parse('[{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio"],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2025dtio","slug":"bateman-2025-dtio-e77d","title":"DTIO: Data Stack for AI-driven Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3733723.3733736","abstract":"HPC, Big Data Analytics, and Machine Learning have become in- creasingly intertwined as popular models such as LLMs and Diffusion Models have been driving discovery in scientific fields. However, each of these domains has its own storage infrastructure with unique I/O interfaces and storage systems, requiring feature sets that are often incompatible. Users with experience in one domain lack the expertise to change their applications to match the data stacks of the other domains, necessitating expensive conversions. There is a need for a transparent solution for the unification of disparate data stacks for the triple convergence of HPC, Big Data, and ML that can provide the required functionality while achieving higher performance. To better support converged HPC, Big Data, and ML workflows, this paper proposes DTIO, a scalable I/O runtime that unifies the disparate I/O stack for modern scientific ML workflows. DTIO utilizes a unique DataTask abstraction to express the move- ment of data, its ordering, and its dependencies on other data as a task. DTIO achieves a unification of scientific and ML workflows by utilizing intelligent mapping of interfaces, and automatically de- termines the best method to relate their unique semantics. DTIO\'s online translation with DataTask caching can improve performance by 49.6% compared to offline translation methods. DTIO also offers numerous optimizations, such as asynchronous I/O and aggregation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2025/bateman-2025-dtio-e77d.pdf"},"tags":["Task Systems","Data Stacks","Systems for AI Workflows"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025unifiedstack","slug":"bateman-2025-unified-data-stack-8de5","title":"A Unified Data Stack for AI Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"}]')}}]);